(()=>{const {t,esc,request,status}=F;let state={connected:false,events:RACE_EVENTS},serial=0;const picker=document.querySelector('#publicRace');function race(){return state.events.find(e=>e.id===picker.value)}function distances(){const e=race();const student=e?.registrationProfile==='student';document.querySelector('#groupForm').hidden=student;const target=document.querySelector('#studentGroupNotice')||document.createElement('p');target.id='studentGroupNotice';target.hidden=!student;if(student)target.innerHTML=t('سجّل كل طالب من صفحة التسجيل الفردي مع موافقة ولي أمره.')+' <a class="btn" href="register.html?event='+encodeURIComponent(e.id)+'">'+t('سجّل مشاركتك')+'</a>';if(!target.parentNode)document.querySelector('#groupForm').before(target);document.querySelectorAll('.member-distance').forEach(select=>{const selected=select.value;select.innerHTML=(e?.distances||[]).map(d=>`<option>${esc(d)}</option>`).join('');if(e?.distances.includes(selected))select.value=selected})}function render(){const selected=picker.value||new URLSearchParams(location.search).get('event');picker.innerHTML=state.events.map(e=>`<option value="${esc(e.id)}">${esc(I18N.event(e).name)}</option>`).join('');if(state.events.some(e=>e.id===selected))picker.value=selected;distances();document.querySelector('#publicNotice').textContent=t(state.connected?'تُحفظ المجموعة كاملة أو لا تُحفظ أي مشاركة عند وجود خطأ.':'هذه معاينة؛ شغّل الخادم لحفظ المجموعة.')}function add(){if(document.querySelectorAll('.member-row').length>=30)return;const article=document.createElement('fieldset');article.className='member-row';article.dataset.member=++serial;article.innerHTML=`<legend>${t('مشارك')} ${serial}</legend><div class="form-grid"><label>${t('الاسم الكامل')}<input data-key="name" required minlength="2" maxlength="100"></label><label>${t('البريد الإلكتروني')}<input data-key="email" type="email" required maxlength="254" dir="ltr"></label><label>${t('رقم واتساب مع رمز الدولة')}<input data-key="phone" required pattern="\\+[1-9][0-9]{7,14}" placeholder="+972501234567" dir="ltr"></label><label>${t('المسافة')}<select data-key="distance" class="member-distance" required></select></label><label>${t('العمر (اختياري)')}<input data-key="age" type="number" min="0" max="100"></label></div><label class="check"><input data-key="emailConsent" type="checkbox">${t('أوافق على استلام تذكير عبر البريد الإلكتروني')}</label><label class="check"><input data-key="whatsappConsent" type="checkbox">${t('أوافق على استلام تذكير عبر واتساب')}</label><button class="outline-btn remove-member" type="button">${t('إزالة')}</button>`;document.querySelector('#groupMembers').append(article);article.querySelectorAll('label').forEach(label=>{const key=label.querySelector('[data-key]')?.dataset.key;const keys={name:'الاسم الكامل',email:'البريد الإلكتروني',phone:'رقم واتساب مع رمز الدولة',distance:'المسافة',age:'العمر (اختياري)',emailConsent:'أوافق على استلام تذكير عبر البريد الإلكتروني',whatsappConsent:'أوافق على استلام تذكير عبر واتساب'};label.dataset.label=keys[key]||''});distances()}document.querySelector('#addMember').addEventListener('click',add);document.querySelector('#groupMembers').addEventListener('click',e=>{if(e.target.closest('.remove-member')&&document.querySelectorAll('.member-row').length>1)e.target.closest('.member-row').remove()});picker.addEventListener('change',distances);F.races().then(s=>{state=s;render()});render();add();window.addEventListener('languagechange',()=>{render();document.querySelectorAll('.member-row label').forEach(label=>{const node=[...label.childNodes].find(n=>n.nodeType===3);if(node&&label.dataset.label)node.textContent=t(label.dataset.label)});document.querySelectorAll('.member-row legend').forEach(el=>el.textContent=t('مشارك')+' '+el.parentElement.dataset.member);document.querySelectorAll('.remove-member').forEach(el=>el.textContent=t('إزالة'));status('')});document.querySelector('#groupForm').addEventListener('submit',async e=>{e.preventDefault();if(!state.connected)return status('هذه معاينة؛ شغّل الخادم لحفظ المجموعة.',true);const members=[...document.querySelectorAll('.member-row')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-key]')].map(input=>[input.dataset.key,input.type==='checkbox'?input.checked:input.value])));if(members.some(m=>!m.emailConsent&&!m.whatsappConsent))return status('اختر قناة واحدة على الأقل لاستلام التذكير.',true);const button=e.target.querySelector('[type=submit]');button.disabled=true;try{const d=await request('/api/groups',{method:'POST',body:JSON.stringify({eventId:picker.value,groupName:e.target.elements.groupName.value,members,language:I18N.lang})});status(d.message);const box=document.querySelector('#groupSuccess');box.hidden=false;box.innerHTML='<h2>'+t('روابط المشاركين الخاصة')+'</h2><p>'+t('احتفظ بهذه الروابط وشارك كل رابط مع صاحبه فقط.')+'</p>'+d.members.map((m,i)=>`<p>${esc(members[i].name)} · #${m.bib} · ${t(m.state)} <a class="outline-btn" href="participant.html#token=${m.participantToken}">${t('صفحتي وبطاقة المشاركة')}</a></p>`).join('');e.target.hidden=true}catch(err){status(err.message,true)}finally{button.disabled=false}})})();
